"""Second curated tranche of materially distinct Python algorithms."""

ADVANCED_TASK_CODE_SPECS_2 = (
    ("count_grid_regions", "Write a Python function that counts four-directionally connected regions of truthy cells in a rectangular grid without mutating the grid.", "def count_grid_regions(grid):\n    if not grid:\n        return 0\n    seen = set()\n    regions = 0\n    for row in range(len(grid)):\n        for column in range(len(grid[0])):\n            if not grid[row][column] or (row, column) in seen:\n                continue\n            regions += 1\n            seen.add((row, column))\n            stack = [(row, column)]\n            while stack:\n                current_row, current_column = stack.pop()\n                for next_row, next_column in ((current_row - 1, current_column), (current_row + 1, current_column), (current_row, current_column - 1), (current_row, current_column + 1)):\n                    if 0 <= next_row < len(grid) and 0 <= next_column < len(grid[0]) and grid[next_row][next_column] and (next_row, next_column) not in seen:\n                        seen.add((next_row, next_column))\n                        stack.append((next_row, next_column))\n    return regions"),
    ("shortest_grid_path", "Write a Python function that returns the minimum number of four-directional moves between two open cells in a rectangular zero-one grid, where zero is open, or None when unreachable.", "def shortest_grid_path(grid, start, goal):\n    if start == goal:\n        return 0\n    distances = {start: 0}\n    queue = [start]\n    position = 0\n    while position < len(queue):\n        row, column = queue[position]\n        position += 1\n        for neighbor in ((row - 1, column), (row + 1, column), (row, column - 1), (row, column + 1)):\n            next_row, next_column = neighbor\n            if 0 <= next_row < len(grid) and 0 <= next_column < len(grid[0]) and grid[next_row][next_column] == 0 and neighbor not in distances:\n                distances[neighbor] = distances[(row, column)] + 1\n                if neighbor == goal:\n                    return distances[neighbor]\n                queue.append(neighbor)\n    return None"),
    ("matrix_multiplication", "Write a Python function that multiplies two compatible rectangular numeric matrices, rejects incompatible dimensions, returns a new matrix, and does not mutate either input.", "def multiply_matrices(left, right):\n    if not left or not right or not right[0] or len(left[0]) != len(right):\n        raise ValueError(\"incompatible matrices\")\n    if any(len(row) != len(left[0]) for row in left) or any(len(row) != len(right[0]) for row in right):\n        raise ValueError(\"matrices must be rectangular\")\n    return [[sum(left[row][inner] * right[inner][column] for inner in range(len(right))) for column in range(len(right[0]))] for row in range(len(left))]"),
    ("rotate_square_matrix", "Write a Python function that returns a new square matrix rotated 90 degrees clockwise, rejects non-square input, and does not mutate the matrix.", "def rotate_square_clockwise(matrix):\n    size = len(matrix)\n    if any(len(row) != size for row in matrix):\n        raise ValueError(\"matrix must be square\")\n    return [[matrix[size - 1 - row][column] for row in range(size)] for column in range(size)]"),
    ("sieve_primes", "Write a Python function that returns every prime number less than or equal to a nonnegative integer using the sieve of Eratosthenes.", "def primes_through(limit):\n    if limit < 2:\n        return []\n    prime = [True] * (limit + 1)\n    prime[0] = prime[1] = False\n    candidate = 2\n    while candidate * candidate <= limit:\n        if prime[candidate]:\n            for multiple in range(candidate * candidate, limit + 1, candidate):\n                prime[multiple] = False\n        candidate += 1\n    return [value for value, is_prime in enumerate(prime) if is_prime]"),
    ("prime_factorization", "Write a Python function that returns the prime factorization of an integer greater than one as a list of factors in ascending order.", "def prime_factors(value):\n    if value <= 1:\n        raise ValueError(\"value must exceed one\")\n    factors = []\n    divisor = 2\n    while divisor * divisor <= value:\n        while value % divisor == 0:\n            factors.append(divisor)\n            value //= divisor\n        divisor += 1\n    if value > 1:\n        factors.append(value)\n    return factors"),
    ("polynomial_evaluation", "Write a Python function that evaluates coefficients ordered from highest to lowest degree at a supplied value using Horner's method without mutating the coefficients.", "def evaluate_polynomial(coefficients, value):\n    result = 0\n    for coefficient in coefficients:\n        result = result * value + coefficient\n    return result"),
    ("longest_increasing_subsequence", "Write a Python function that returns the length of the longest strictly increasing subsequence in a numeric sequence using binary-search tails and without mutating the input.", "def increasing_subsequence_length(values):\n    tails = []\n    for value in values:\n        left, right = 0, len(tails)\n        while left < right:\n            middle = (left + right) // 2\n            if tails[middle] < value:\n                left = middle + 1\n            else:\n                right = middle\n        if left == len(tails):\n            tails.append(value)\n        else:\n            tails[left] = value\n    return len(tails)"),
    ("longest_common_subsequence", "Write a Python function that returns the length of the longest common subsequence of two strings using dynamic programming and one row of storage.", "def common_subsequence_length(first, second):\n    previous = [0] * (len(second) + 1)\n    for left_character in first:\n        current = [0]\n        for index, right_character in enumerate(second, 1):\n            if left_character == right_character:\n                current.append(previous[index - 1] + 1)\n            else:\n                current.append(max(previous[index], current[-1]))\n        previous = current\n    return previous[-1]"),
    ("minimum_coin_count", "Write a Python function that returns the minimum number of positive-denomination coins needed to make an exact nonnegative amount, or None when impossible.", "def minimum_coins(denominations, amount):\n    best = [0] + [None] * amount\n    for subtotal in range(1, amount + 1):\n        candidates = [best[subtotal - coin] + 1 for coin in denominations if 0 < coin <= subtotal and best[subtotal - coin] is not None]\n        if candidates:\n            best[subtotal] = min(candidates)\n    return best[amount]"),
    ("zero_one_knapsack", "Write a Python function that returns the maximum value obtainable within a nonnegative capacity from paired positive weights and values, using each item at most once.", "def maximum_knapsack_value(weights, values, capacity):\n    if len(weights) != len(values):\n        raise ValueError(\"weights and values must align\")\n    best = [0] * (capacity + 1)\n    for weight, value in zip(weights, values):\n        if weight <= 0:\n            raise ValueError(\"weights must be positive\")\n        for remaining in range(capacity, weight - 1, -1):\n            best[remaining] = max(best[remaining], best[remaining - weight] + value)\n    return best[capacity]"),
    ("subset_sum", "Write a Python function that reports whether some subset of nonnegative integers sums exactly to a nonnegative target without mutating the input.", "def has_subset_sum(values, target):\n    reachable = {0}\n    for value in values:\n        if value < 0:\n            raise ValueError(\"values must be nonnegative\")\n        reachable.update(subtotal + value for subtotal in tuple(reachable) if subtotal + value <= target)\n    return target in reachable"),
    ("cartesian_product", "Write a Python function that returns the Cartesian product of a sequence of input sequences as tuples, including one empty tuple for no input sequences.", "def cartesian_product(sequences):\n    result = [()]\n    for sequence in sequences:\n        result = [prefix + (value,) for prefix in result for value in sequence]\n    return result"),
    ("power_set", "Write a Python function that returns every subset of a sequence as tuples in iterative construction order without mutating the input.", "def power_set(values):\n    subsets = [()]\n    for value in values:\n        subsets.extend(subset + (value,) for subset in tuple(subsets))\n    return subsets"),
    ("unique_permutations", "Write a Python function that returns all distinct permutations of a possibly repeated sequence as tuples without mutating the input.", "def unique_permutations(values):\n    counts = {}\n    for value in values:\n        counts[value] = counts.get(value, 0) + 1\n    result = []\n    current = []\n    def build():\n        if len(current) == len(values):\n            result.append(tuple(current))\n            return\n        for value in counts:\n            if counts[value]:\n                counts[value] -= 1\n                current.append(value)\n                build()\n                current.pop()\n                counts[value] += 1\n    build()\n    return result"),
    ("roman_numeral_parse", "Write a Python function that converts a valid uppercase Roman numeral to an integer by accounting for subtractive pairs.", "def roman_to_integer(text):\n    values = {\"I\": 1, \"V\": 5, \"X\": 10, \"L\": 50, \"C\": 100, \"D\": 500, \"M\": 1000}\n    total = 0\n    previous = 0\n    for character in reversed(text):\n        value = values[character]\n        if value < previous:\n            total -= value\n        else:\n            total += value\n            previous = value\n    return total"),
    ("integer_base_conversion", "Write a Python function that converts a nonnegative integer to a string in base 2 through 36 using uppercase digits and without library conversion helpers.", "def integer_to_base(value, base):\n    if value < 0 or not 2 <= base <= 36:\n        raise ValueError(\"invalid value or base\")\n    digits = \"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ\"\n    if value == 0:\n        return \"0\"\n    result = []\n    while value:\n        value, remainder = divmod(value, base)\n        result.append(digits[remainder])\n    return \"\".join(reversed(result))"),
    ("quoted_field_split", "Write a Python function that splits a line on a one-character delimiter while preserving delimiters inside double-quoted fields and removing the surrounding quotes.", "def split_quoted_fields(line, delimiter=\",\"):\n    fields = []\n    current = []\n    quoted = False\n    for character in line:\n        if character == '\"':\n            quoted = not quoted\n        elif character == delimiter and not quoted:\n            fields.append(\"\".join(current))\n            current = []\n        else:\n            current.append(character)\n    if quoted:\n        raise ValueError(\"unclosed quote\")\n    fields.append(\"\".join(current))\n    return fields"),
    ("word_wrap", "Write a Python function that greedily wraps whitespace-separated words into lines no longer than a positive width and raises an error when a single word exceeds the width.", "def wrap_words(text, width):\n    if width <= 0:\n        raise ValueError(\"width must be positive\")\n    lines = []\n    current = []\n    length = 0\n    for word in text.split():\n        if len(word) > width:\n            raise ValueError(\"word exceeds width\")\n        required = len(word) if not current else len(word) + 1\n        if length + required > width:\n            lines.append(\" \".join(current))\n            current = [word]\n            length = len(word)\n        else:\n            current.append(word)\n            length += required\n    if current:\n        lines.append(\" \".join(current))\n    return lines"),
    ("weighted_group_average", "Write a Python function that computes a weighted average for each group from records containing group, value, and nonnegative weight fields, omitting groups with zero total weight.", "def weighted_averages_by_group(records):\n    weighted_totals = {}\n    weights = {}\n    for row in records:\n        if row[\"weight\"] < 0:\n            raise ValueError(\"weight must be nonnegative\")\n        group = row[\"group\"]\n        weighted_totals[group] = weighted_totals.get(group, 0) + row[\"value\"] * row[\"weight\"]\n        weights[group] = weights.get(group, 0) + row[\"weight\"]\n    return {group: weighted_totals[group] / weight for group, weight in weights.items() if weight}"),
    ("linear_interpolation", "Write a Python function that linearly interpolates a query position from sorted distinct x coordinates and aligned y values, returning endpoint values outside the coordinate range.", "def interpolate_linear(xs, ys, query):\n    if len(xs) != len(ys) or not xs:\n        raise ValueError(\"coordinates must align\")\n    if query <= xs[0]:\n        return ys[0]\n    if query >= xs[-1]:\n        return ys[-1]\n    right = 1\n    while xs[right] < query:\n        right += 1\n    left = right - 1\n    fraction = (query - xs[left]) / (xs[right] - xs[left])\n    return ys[left] + fraction * (ys[right] - ys[left])"),
    ("piecewise_histogram", "Write a Python function that counts numeric values into consecutive half-open bins defined by strictly increasing boundaries and returns an overflow count for values at or above the final boundary.", "def histogram_by_boundaries(values, boundaries):\n    if len(boundaries) < 2 or any(boundaries[index] >= boundaries[index + 1] for index in range(len(boundaries) - 1)):\n        raise ValueError(\"boundaries must increase\")\n    counts = [0] * (len(boundaries) - 1)\n    overflow = 0\n    for value in values:\n        if value < boundaries[0]:\n            continue\n        index = 0\n        while index + 1 < len(boundaries) and value >= boundaries[index + 1]:\n            index += 1\n        if index == len(counts):\n            overflow += 1\n        else:\n            counts[index] += 1\n    return counts, overflow"),
    ("round_robin_schedule", "Write a Python function that creates a single round-robin schedule for distinct participants, uses None as a bye when necessary, and returns each round as a list of pairs.", "def round_robin_schedule(participants):\n    players = list(participants)\n    if len(players) % 2:\n        players.append(None)\n    rounds = []\n    for _ in range(max(0, len(players) - 1)):\n        pairs = []\n        for index in range(len(players) // 2):\n            first = players[index]\n            second = players[-1 - index]\n            if first is not None and second is not None:\n                pairs.append((first, second))\n        rounds.append(pairs)\n        players = [players[0], players[-1]] + players[1:-1]\n    return rounds"),
    ("allocate_largest_remainder", "Write a Python function that allocates an integer total proportionally to nonnegative weights using the largest-remainder method and returns allocations in input order.", "def allocate_largest_remainder(total, weights):\n    weight_sum = sum(weights)\n    if total < 0 or weight_sum <= 0 or any(weight < 0 for weight in weights):\n        raise ValueError(\"invalid total or weights\")\n    quotas = [total * weight / weight_sum for weight in weights]\n    allocations = [int(quota) for quota in quotas]\n    remaining = total - sum(allocations)\n    order = sorted(range(len(weights)), key=lambda index: (-(quotas[index] - allocations[index]), index))\n    for index in order[:remaining]:\n        allocations[index] += 1\n    return allocations"),
)
